INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 7, "2030/12/17 14:59:59", 0.0, 7001, 0.0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 7, "2030/12/17 14:59:59", 0.0, 7002, 0.0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 7, "2030/12/17 14:59:59", 0.0, 7003, 0.0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 10, "2030/12/17 14:59:59", 0.0, 10001, 0.0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 10, "2030/12/17 14:59:59", 0.0, 10002, 0.0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 10, "2030/12/17 14:59:59", 0.0, 10003, 0.0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 10, "2030/12/17 14:59:59", 0.0, 10004, 0.0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -416.5, 1, 105801, 12, "2030/12/17 14:59:59", 0.0, 12001, 0.0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 13, "2030/12/17 14:59:59", 0.0, 13001, 0.0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 13, "2030/12/17 14:59:59", 0.0, 13002, 0.0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 13, "2030/12/17 14:59:59", 0.0, 13003, 0.0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 13, "2030/12/17 14:59:59", 0.0, 13004, 0.0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 14, "2030/12/17 14:59:59", 0.0, 14001, 0.0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 14, "2030/12/17 14:59:59", 0.0, 14002, 0.0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 14, "2030/12/17 14:59:59", 0.0, 14003, 0.0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 14, "2030/12/17 14:59:59", 0.0, 14004, 0.0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -470.0, 1, 105901, 15, "2030/12/17 14:59:59", 0.0, 15001, 0.0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 16, "2030/12/17 14:59:59", 0.0, 16001, 0.0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 16, "2030/12/17 14:59:59", 0.0, 16002, 0.0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 16, "2030/12/17 14:59:59", 0.0, 16003, 0.0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 16, "2030/12/17 14:59:59", 0.0, 16004, 0.0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 17, "2030/12/17 14:59:59", 0.0, 17002, 0.0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 25, "2030/12/17 14:59:59", 0.0, 17004, 0.0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 25, "2030/12/17 14:59:59", 0.0, 17005, 0.0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 25, "2030/12/17 14:59:59", 0.0, 17006, 0.0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 25, "2030/12/17 14:59:59", 0.0, 17007, 0.0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 190801, 18, "2030/12/17 14:59:59", 0.0, 18001, 0.0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 2, "2015/12/17 15:00:00", 0, -363.0, 1, 190801, 18, "2030/12/17 14:59:59", 0.0, 18002, 0.0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 3, "2015/12/17 15:00:00", 0, -470.0, 1, 190801, 19, "2030/12/17 14:59:59", 0.0, 19001, 0.0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 4, "2015/12/17 15:00:00", 0, -470.0, 1, 190801, 19, "2030/12/17 14:59:59", 0.0, 19002, 0.0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 5, "2015/12/17 15:00:00", 0, -470.0, 1, 190801, 20, "2030/12/17 14:59:59", 0.0, 20001, 0.0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 6, "2015/12/17 15:00:00", 0, -470.0, 1, 190801, 20, "2030/12/17 14:59:59", 0.0, 20002, 0.0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 21, "2030/12/17 14:59:59", 0.0, 21001, 0.0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 21, "2030/12/17 14:59:59", 0.0, 21002, 0.0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 21, "2030/12/17 14:59:59", 0.0, 21003, 0.0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 21, "2030/12/17 14:59:59", 0.0, 21004, 0.0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 1, "2015/12/17 15:00:00", 0, -430.0, 1, 190801, 22, "2030/12/17 14:59:59", 0.0, 22001, 0.0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 2, "2015/12/17 15:00:00", 0, -430.0, 1, 190801, 22, "2030/12/17 14:59:59", 0.0, 22002, 0.0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 3, "2015/12/17 15:00:00", 0, -430.0, 1, 190801, 23, "2030/12/17 14:59:59", 0.0, 23001, 0.0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 4, "2015/12/17 15:00:00", 0, -430.0, 1, 190801, 23, "2030/12/17 14:59:59", 0.0, 23002, 0.0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 1, "2019/01/31 12:00:00", 10011, -385.0, 1, 109001, 24, "2030/12/17 14:59:59", 4.08, 24001, 8.0, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 2, "2019/01/31 12:00:00", 10011, -385.0, 1, 109001, 24, "2030/12/17 14:59:59", 5.0, 24002, 8.0, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 3, "2019/01/31 12:00:00", 10011, -385.0, 1, 109001, 24, "2030/12/17 14:59:59", 10.11, 24003, 8.0, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 4, "2019/01/31 12:00:00", 10011, -385.0, 1, 109001, 24, "2030/12/17 14:59:59", 4.0, 24004, 8.0, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 5, "2019/01/31 12:00:00", 10011, -385.0, 1, 109001, 24, "2030/12/17 14:59:59", 6.0, 24005, 8.0, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 6, "2019/01/31 12:00:00", 10011, 0.0, 1, 109002, 24, "2030/12/17 14:59:59", 0.0, 24006, 0.0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 7, "2019/01/31 12:00:00", 10011, 0.0, 1, 109002, 24, "2030/12/17 14:59:59", 0.0, 24007, 0.0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 8, "2019/01/31 12:00:00", 10011, 0.0, 1, 109002, 24, "2030/12/17 14:59:59", 0.0, 24008, 0.0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 9, "2019/01/31 12:00:00", 10011, 0.0, 1, 109002, 24, "2030/12/17 14:59:59", 0.0, 24009, 0.0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("エリコ（バレンタイン）", 10, "2019/01/31 12:00:00", 10011, 0.0, 1, 109002, 24, "2030/12/17 14:59:59", 0.0, 24010, 0.0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 1, "2019/01/31 12:00:00", 10011, -385.0, 1, 109101, 24, "2030/12/17 14:59:59", 2.12, 24011, 8.0, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 2, "2019/01/31 12:00:00", 10011, -385.0, 5, 109101, 24, "2030/12/17 14:59:59", 4.19, 24012, 8.0, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 3, "2019/01/31 12:00:00", 10011, -385.0, 2, 109101, 24, "2030/12/17 14:59:59", 2.3, 24013, 8.0, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 4, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 4, "2019/01/31 12:00:00", 10011, 0.0, 1, 109102, 24, "2030/12/17 14:59:59", 0.0, 24014, 0.0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 5, "2019/01/31 12:00:00", 10011, -385.0, 5, 109101, 24, "2030/12/17 14:59:59", 5.23, 24015, 8.0, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 6, "2019/01/31 12:00:00", 10011, 0.0, 1, 109102, 24, "2030/12/17 14:59:59", 0.0, 24016, 0.0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 7, "2019/01/31 12:00:00", 10011, -385.0, 1, 109101, 24, "2030/12/17 14:59:59", 5.01, 24017, 8.0, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 8, "2019/01/31 12:00:00", 10011, 0.0, 1, 109102, 24, "2030/12/17 14:59:59", 0.0, 24018, 0.0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 9, "2019/01/31 12:00:00", 10011, 0.0, 1, 109102, 24, "2030/12/17 14:59:59", 0.0, 24019, 0.0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル（バレンタイン）", 10, "2019/01/31 12:00:00", 10011, 0.0, 1, 109102, 24, "2030/12/17 14:59:59", 0.0, 24020, 0.0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 26, "2030/12/17 14:59:59", 0.0, 26001, 0.0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 26, "2030/12/17 14:59:59", 0.0, 26002, 0.0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 26, "2030/12/17 14:59:59", 0.0, 26003, 0.0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 26, "2030/12/17 14:59:59", 0.0, 26004, 0.0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シェフィ", 1, "2015/12/17 15:00:00", 0, -363.0, 2, 106401, 27, "2030/12/17 14:59:59", 0.0, 27001, 0.0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 1, 2104010);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 27, "2030/12/17 14:59:59", 0.0, 27002, 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 27, "2030/12/17 14:59:59", 0.0, 27003, 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 27, "2030/12/17 14:59:59", 0.0, 27004, 0.0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 1, "2019/09/24 15:00:00", 0, -363.0, 1, 190801, 28, "2030/12/17 14:59:59", 0.0, 28001, 0.0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 1, 0);
