INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 4, "2019/09/24 15:00:00", 0, -409.0, 1, 190801, 29, "2030/12/17 14:59:59", 0.0, 29002, 0.0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("カリン", 5, "2019/09/24 15:00:00", 0, -409.0, 1, 190801, 30, "2030/12/17 14:59:59", 0.0, 30001, 0.0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 1, 0);
