INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -416.5, 1, 106001, 42, "2030/12/17 14:59:59", 0.0, 42004, 0.0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("ペコリーヌ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105801, 43, "2030/12/17 14:59:59", 0.0, 43001, 0.0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("コッコロ", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 105901, 43, "2030/12/17 14:59:59", 0.0, 43002, 0.0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("キャル", 1, "2015/12/17 15:00:00", 0, -363.0, 1, 106001, 43, "2030/12/17 14:59:59", 0.0, 43003, 0.0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("アメス", 1, "2015/12/17 15:00:00", 0, -416.5, 1, 123001, 44, "2030/12/17 14:59:59", 0.0, 43004, 0.0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("アメス", 2, "2015/12/17 15:00:00", 0, -416.5, 1, 123001, 44, "2030/12/17 14:59:59", 0.0, 43005, 0.0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("アメス", 3, "2015/12/17 15:00:00", 0, -416.5, 1, 123001, 45, "2030/12/17 14:59:59", 5.79, 43006, 0.0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("アメス", 1, "2015/12/17 15:00:00", 0, -371.5, 1, 123001, 46, "2030/12/17 14:59:59", 0.0, 46001, 0.0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 1, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("シズル", 1, "2015/12/17 15:00:00", 0, -416.5, 2, 104901, 47, "2030/12/17 14:59:59", 0.0, 47001, 0.0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 2, 0);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES ("リノ", 1, "2015/12/17 15:00:00", 0, -416.5, 1, 101101, 47, "2030/12/17 14:59:59", 9.32, 47002, 0.0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 2, 0);
